with latest as (select * from customers qualify row_number() over (partition by segment, country order by credit_limit desc nulls first, id) = 1) select id, name, email, city, segment, signup_date, age, case when name rlike '^(David Lee |Pim Chaiyaporn)$' then 'GROUP_B' when name rlike '^(Alice Wong|bob smith)$' then 'PRIORITY' else 'CORE' end as name_zone from latest order by city desc nulls first;
